            border-radius: 6px 0 0 6px; /* Rounded on left */
        }
        .pk-bar-right { /* Renamed class */
            background: linear-gradient(to left, #2193b0, #6dd5ed); /* Cooler gradient */
            border-radius: 0 6px 6px 0; /* Rounded on right */
        }
        /* Modified Side Styles */
        .pk-side {
            display: flex;
            align-items: center;
            flex: 1 1 auto; /* Allow grow/shrink, basis auto */
