                 const handleMouseMove = (e) => { if (!isDragging) return; let newX = e.clientX - offsetX; let newY = e.clientY - offsetY; try{ const boundaryContainer = document.querySelector('.container') || document.body; /* USE .container FOR BOUNDS */ const containerWidth = boundaryContainer.offsetWidth; const containerHeight = boundaryContainer.offsetHeight; const panelWidth = panelWindow.offsetWidth; const panelHeight = panelWindow.offsetHeight; const minBoundX = 0; const minBoundY = 0; const maxBoundX = containerWidth - panelWidth; const maxBoundY = containerHeight - panelHeight; /* console.log(`[Draggable Bounds] ContW: ${containerWidth}, ContH: ${containerHeight}, PanelW: ${panelWidth}, PanelH: ${panelHeight}, MaxX: ${maxBoundX}, MaxY: ${maxBoundY}`); /* DEBUG LOG */ /* Clamp position within container bounds */ newX = Math.max(minBoundX, Math.min(newX, maxBoundX)); newY = Math.max(minBoundY, Math.min(newY, maxBoundY)); } catch(e){ console.error("Error calculating drag bounds:", e); } /* console.log(`[Draggable MouseMove] ID: ${panelWindow.id}, NewX: ${newX}, NewY: ${newY}`); /* DEBUG LOG */ panelWindow.style.left = `${newX}px`; panelWindow.style.top = `${newY}px`; };
