            function handleNewAiOutput(aiText) {
                console.log("[直播.html] handleNewAiOutput received raw text:\n", aiText);

                const startMarker = "=== LIVE DATA START ===";
                const endMarker = "=== LIVE DATA END ===";
                let contentToParse = aiText; // Default to original text

                const startIndex = aiText.indexOf(startMarker);
                const endIndex = aiText.indexOf(endMarker);

                if (startIndex !== -1 && endIndex !== -1 && startIndex < endIndex) {
                    // Markers found in correct order, extract content between them
                    contentToParse = aiText.substring(startIndex + startMarker.length, endIndex).trim();
                    console.log("[直播.html] handleNewAiOutput: Extracted content between markers:\n", contentToParse);
                } else if (startIndex !== -1 || endIndex !== -1) {
                    // Only one marker found, or markers in wrong order
                    console.warn("[直播.html] handleNewAiOutput: Found markers but in wrong order or incomplete. Attempting to parse original text.");
                    // contentToParse remains aiText
                } else {
                    // Neither marker found
                    console.warn("[直播.html] handleNewAiOutput: Start/End markers not found. Attempting to parse original text.");
                    // contentToParse remains aiText
                }

                // Attempt to parse the (potentially extracted) content
                const parsedData = parseLiveData(contentToParse);
                if (parsedData) {
                    updateUI(parsedData);
                } else {
                    console.error("[直播.html] handleNewAiOutput: Failed to parse data from content:\n", contentToParse);
                }
            } // End of handleNewAiOutput function

