  <script>
    // --- 优化后的 JavaScript (v7.3 - 性能优化) ---

    function formatSingleList(ulElement) {
        if (!ulElement || ulElement.querySelector('li')) return;
        const rawText = ulElement.textContent.trim();
        ulElement.innerHTML = '';
        if (rawText && rawText.toLowerCase() !== '无' && !rawText.startsWith('(')) {
            const items = rawText.split('\n');
            const fragment = document.createDocumentFragment();
            items.forEach(itemText => {
                if (itemText.trim()) {
                    const li = document.createElement('li');
                    li.textContent = itemText.trim();
                    fragment.appendChild(li);
                }
            });
            ulElement.appendChild(fragment);
        } else if (rawText) {
            const li = document.createElement('li');
            li.textContent = rawText;
            li.style.borderLeftColor = 'var(--text-muted-color)';
            li.style.fontStyle = 'italic';
            ulElement.appendChild(li);
        } else {
            const li = document.createElement('li');
            li.textContent = '(数据为空)';
            li.style.borderLeftColor = 'var(--text-muted-color)';
            li.style.fontStyle = 'italic';
            ulElement.appendChild(li);
        }
    }

    function updateProgressBar() {
        const expTextElement = document.getElementById('exp-text');
        const progressBarElement = document.getElementById('exp-progress');
        if (expTextElement && progressBarElement) {
            const expMatch = expTextElement.textContent.match(/([\d,.]+)\s*\/\s*([\d,.]+)/);
            if (expMatch && expMatch.length === 3) {
                const currentExp = parseFloat(expMatch[1].replace(/,/g, '')) || 0;
                const requiredExp = parseFloat(expMatch[2].replace(/,/g, '')) || 1;
                const percentage = Math.min(100, Math.max(0, (currentExp / requiredExp) * 100));
                progressBarElement.style.width = percentage + '%';
            } else { progressBarElement.style.width = '0%'; }
        } else { if(progressBarElement) progressBarElement.style.width = '0%'; }
    }

    /**
     * !!! 重要：模拟您的应用中数据填充的完成时机 !!!
     * 您需要确保您的系统逻辑（替换 $1..$20 占位符）在此 Promise resolve 之前完成。
     * 如果您的数据填充很快或者是同步的，可以减小或移除 setTimeout 的延迟。
     */
    function signalDataReady() {
        console.log("假定外部数据填充过程开始...");
        // PERFORMANCE TIP: 如果您的数据填充是同步的，或者非常快，
        // 可以将 setTimeout 的延迟降为 0，甚至直接 resolve()。
        // 如果数据填充依赖其他异步操作，确保此 Promise 等待它们完成。
        return new Promise(resolve => {
            setTimeout(() => {
                console.log("假定外部数据填充过程已完成。UI 格式化即将开始。");
                resolve();
            }, 0); // 将延迟降至0，使其在当前宏任务队列末尾执行，或根据实际情况调整
        });
    }

    /**
     * 分批处理任务，避免长时间阻塞主线程
     * @param {Array<Function>} tasks - 需要执行的任务函数数组
     * @param {Function} onComplete - 所有任务完成后调用的回调
     */
    function processTasksInBatches(tasks, onComplete) {
        let currentIndex = 0;
        const batchSize = 2; // 每次处理的任务数，可以根据实际情况调整

        function runNextBatch() {
            if (currentIndex >= tasks.length) {
                if (typeof onComplete === 'function') {
                    onComplete();
                }
                return;
            }

            const endTime = performance.now() + 5; // 每批任务最多执行5毫秒
            let batchCount = 0;

            while (performance.now() < endTime && currentIndex < tasks.length && batchCount < batchSize) {
                try {
                    tasks[currentIndex]();
                } catch (e) {
                    console.error("Error processing task:", e, tasks[currentIndex]);
                }
                currentIndex++;
                batchCount++;
            }
            // 使用 requestAnimationFrame 来调度下一批，效果通常比 setTimeout(0) 更平滑
            requestAnimationFrame(runNextBatch);
        }
        requestAnimationFrame(runNextBatch); // 启动第一批
    }

    // --- 初始化逻辑 ---
    // 假设页面上有一个 loading 指示器
    // const loadingIndicator = document.getElementById('loading-indicator');
    // if (loadingIndicator) loadingIndicator.style.display = 'block';

    signalDataReady()
        .then(() => {
            console.log("数据已加载，开始分批格式化UI...");

            const itemLists = Array.from(document.querySelectorAll('.item-list'));
            const formattingTasks = itemLists.map(listElement => {
                // 为每个列表创建一个格式化任务函数
                return () => formatSingleList(listElement);
            });

            // 将进度条更新作为最后一个任务，或者在所有列表格式化后单独执行
            // formattingTasks.push(updateProgressBar); // 也可以这样做

            processTasksInBatches(formattingTasks, () => {
                // 所有列表格式化完成后，最后更新进度条
                updateProgressBar();
                console.log("所有UI格式化任务完成。");
                // if (loadingIndicator) loadingIndicator.style.display = 'none';
            });
        })
        .catch(error => {
            console.error("初始化过程中出错:", error);
            // if (loadingIndicator) loadingIndicator.style.display = 'none'; // 出错也要隐藏
        });

  </script>
