            // --- Resizable Function ---
            function makeResizable(panelElement) {
                const resizer = panelElement.querySelector('.resizer');
                if (!resizer) return;

                let isResizing = false;
                let startX, startY, initialWidth, initialHeight;

                const handleMouseDown = (e) => {
                    if (e.button !== 0) return; // Only left click
                    isResizing = true;
                    startX = e.clientX;
                    startY = e.clientY;
                    initialWidth = panelElement.offsetWidth;
                    initialHeight = panelElement.offsetHeight;
                    panelElement.style.cursor = 'nwse-resize';
                    document.body.style.cursor = 'nwse-resize'; // Apply to body to avoid losing cursor style
                    e.preventDefault();

                    document.addEventListener('mousemove', handleMouseMove);
                    document.addEventListener('mouseup', handleMouseUp);
                };

                const handleMouseMove = (e) => {
                    if (!isResizing) return;
                    const newWidth = Math.max(MIN_PANEL_WIDTH, initialWidth + (e.clientX - startX));
                    const newHeight = Math.max(MIN_PANEL_HEIGHT, initialHeight + (e.clientY - startY));
                    console.log(`[Resizable MouseMove] ID: ${panelElement.id}, NewWidth: ${newWidth}, NewHeight: ${newHeight}`); /* DEBUG LOG */
                    panelElement.style.width = `${newWidth}px`;
                    panelElement.style.height = `${newHeight}px`;
                };

                const handleMouseUp = (e) => {
                    if (e.button !== 0) return;
                    if (isResizing) {
                        isResizing = false;
                        panelElement.style.cursor = 'default'; // Or 'move' if header is default
                        document.body.style.cursor = 'default';
                        document.removeEventListener('mousemove', handleMouseMove);
                        document.removeEventListener('mouseup', handleMouseUp);
                        savePanelState(panelElement); // Save state after resize
                        // *** Conditionally call adjustPerformanceAreaPadding ***
                        if (panelElement.id !== 'right-panel-window') { // <-- ADD THIS CHECK
                            adjustPerformanceAreaPadding(); // Adjust padding ONLY if it's NOT the info panel
                        } else {
                             console.log(`[直播.html] Skipping padding adjustment after resizing ${panelElement.id}`);
                        }
                    }
                };

                // Touch events (simplified version, might need refinement for precision)
                const handleTouchStart = (e) => {
                    isResizing = true;
                    const touch = e.touches[0];
                    startX = touch.clientX;
                    startY = touch.clientY;
                    initialWidth = panelElement.offsetWidth;
                    initialHeight = panelElement.offsetHeight;
                    e.preventDefault();

                    document.addEventListener('touchmove', handleTouchMove, { passive: false });
                    document.addEventListener('touchend', handleTouchEnd);
                };

                const handleTouchMove = (e) => {
                    if (!isResizing) return;
                    const touch = e.touches[0];
                    const newWidth = Math.max(MIN_PANEL_WIDTH, initialWidth + (touch.clientX - startX));
                    const newHeight = Math.max(MIN_PANEL_HEIGHT, initialHeight + (touch.clientY - startY));
                    console.log(`[Resizable TouchMove] ID: ${panelElement.id}, NewWidth: ${newWidth}, NewHeight: ${newHeight}`); /* DEBUG LOG */
                    panelElement.style.width = `${newWidth}px`;
                    panelElement.style.height = `${newHeight}px`;
                    e.preventDefault();
                };

                const handleTouchEnd = () => {
                    if (isResizing) {
                        isResizing = false;
                        document.removeEventListener('touchmove', handleTouchMove);
