            // --- Robust Parsing Function (using Regex) ---
            function parseLiveData(aiOutput) {
                const data = {};
                // Regex to find [KEY: value] pairs, handling multi-line values correctly.
                // It captures the KEY and the value, stopping before the next [KEY: or end of string.
                const regex = /\[([A-Z_]+):\s*([\s\S]*?)\](?=\s*(?:\[[A-Z_]+:|$))/g;
                let match;

                console.log("[直播.html] parseLiveData: Starting regex parsing on content:", aiOutput);

                while ((match = regex.exec(aiOutput)) !== null) {
                    const key = match[1];
                    const value = match[2].trim(); // Trim whitespace from the captured value
                    data[key] = value;
                    console.log(`[直播.html] parseLiveData: Regex found Key='${key}', Value='${value}'`);
                }

                if (Object.keys(data).length === 0) {
                    console.warn("[直播.html] parseLiveData: No [KEY: value] pairs were successfully parsed using regex. Content:", aiOutput);
                    return null; // Return null if nothing was parsed
                }

                console.log("[直播.html] parseLiveData: Successfully parsed data via regex:", data);
                return data;
            } // End of parseLiveData function

