            // Ensure clean separation before the next function
            function handleNewAiOutput(aiText) {
                console.log("[直播.html] handleNewAiOutput received raw text:\n", aiText);

                const startMarker = "=== LIVE DATA START ===";
                const endMarker = "=== LIVE DATA END ===";
                let contentToParse = aiText; // Default to original text

                const startIndex = aiText.indexOf(startMarker);
                const endIndex = aiText.indexOf(endMarker);

                if (startIndex !== -1 && endIndex !== -1 && startIndex < endIndex) {
                    // Markers found in correct order, extract content between them
                    contentToParse = aiText.substring(startIndex + startMarker.length, endIndex).trim();
                    console.log("[直播.html] handleNewAiOutput: Extracted content between markers:\n", contentToParse);
                } else if (startIndex !== -1 || endIndex !== -1) {
                    // Only one marker found, or markers in wrong order
                    console.warn("[直播.html] handleNewAiOutput: Found markers but in wrong order or incomplete. Attempting to parse original text.");
                    // contentToParse remains aiText
                } else {
                    // Neither marker found
                    console.warn("[直播.html] handleNewAiOutput: Start/End markers not found. Attempting to parse original text.");
                    // contentToParse remains aiText
                }

                // Attempt to parse the (potentially extracted) content
                const parsedData = parseLiveData(contentToParse);
                if (parsedData) {
                    updateUI(parsedData);
                } else {
                    console.error("[直播.html] handleNewAiOutput: Failed to parse data from content:\n", contentToParse);
                }
            } // End of handleNewAiOutput function

            // --- Define New Function for Padding Adjustment (Simplified) ---
            function adjustPerformanceAreaPadding() {
                const performanceArea = document.querySelector('.performance-area');
                const leftPanel = document.getElementById('left-panel-window');
                const leaderboardPanel = document.getElementById('leaderboard-panel');
                const streamerInfoPanel = document.getElementById('streamer-info-panel'); // Get new panel
                const root = document.documentElement;

                if (!performanceArea || !root) {
                    console.warn("[直播.html] adjustPerformanceAreaPadding: Could not find performanceArea or root element.");
                    return;
                }

                const panelGap = parseInt(root.style.getPropertyValue('--panel-gap') || '15');
                let paddingLeft = panelGap;
                let paddingRight = panelGap; // Start with default gap

                // --- Left Padding Calculation (Simplified) ---
                if (leftPanel && !leftPanel.classList.contains('hidden')) {
                    try {
                        const leftPanelRect = leftPanel.getBoundingClientRect();
                        // Assume if visible, it requires padding
                        paddingLeft = Math.round(leftPanelRect.width) + (2 * panelGap);
                        console.log(`[直播.html] Left panel visible. Width: ${leftPanelRect.width}, Calculated paddingLeft: ${paddingLeft}`);
                    } catch (e) {
                        console.error("[直播.html] Error getting left panel width:", e);
                        paddingLeft = 250 + (2 * panelGap); // Fallback
                    }
                } else {
                    console.log(`[直播.html] Left panel hidden or not found. Setting paddingLeft to base gap: ${paddingLeft}`);
                }

                // --- Right Padding Calculation (Considering Leaderboard AND Streamer Info) ---
                let rightPanelWidth = 0;
                let rightPanelVisible = false;

                if (leaderboardPanel && !leaderboardPanel.classList.contains('hidden')) {
                    try {
                        rightPanelWidth = Math.max(rightPanelWidth, Math.round(leaderboardPanel.getBoundingClientRect().width));
                        rightPanelVisible = true;
                        console.log(`[直播.html] Leaderboard visible. Current max right width: ${rightPanelWidth}`);
                    } catch (e) { console.error("[直播.html] Error getting leaderboard panel width:", e); }
                }
                if (streamerInfoPanel && !streamerInfoPanel.classList.contains('hidden')) {
                    try {
                        rightPanelWidth = Math.max(rightPanelWidth, Math.round(streamerInfoPanel.getBoundingClientRect().width));
                        rightPanelVisible = true;
                        console.log(`[直播.html] Streamer Info visible. Current max right width: ${rightPanelWidth}`);
                    } catch (e) { console.error("[直播.html] Error getting streamer info panel width:", e); }
                }

                if (rightPanelVisible) {
                    paddingRight = rightPanelWidth + (2 * panelGap);
                    console.log(`[直播.html] Right panel(s) visible. Max width: ${rightPanelWidth}. Calculated paddingRight: ${paddingRight}`);
                } else {
                    paddingRight = panelGap; // Default gap if no right panels are visible
                    console.log(`[直播.html] No right panels visible. Setting paddingRight to base gap: ${paddingRight}`);
                }


                // Apply calculated padding
                performanceArea.style.paddingLeft = `${paddingLeft}px`;
                performanceArea.style.paddingRight = `${paddingRight}px`;
                console.log(`[直播.html] Final Applied Padding: Left=${paddingLeft}px, Right=${paddingRight}px`);
            } // End of adjustPerformanceAreaPadding function

