            // Panel Toggles - Modified for Mobile Overlays AND Desktop State/Padding
            const setupPanelToggle = (button, panel) => {
                if (!button || !panel) return;
                const panelId = panel.id; // Get panel ID for logging and state key
                const panelStateKey = `livePanelVisibility_${panelId}`; // Use a distinct key for visibility

                button.addEventListener('click', () => {
                    const isCurrentlyHidden = panel.classList.contains('hidden');
                    const targetVisibleState = isCurrentlyHidden; // If hidden, target is visible, vice-versa

                    console.log(`[直播.html] Toggle button clicked for panel: ${panelId}. Currently hidden: ${isCurrentlyHidden}. Target state: ${targetVisibleState ? 'visible' : 'hidden'}`);

                    if (isMobile()) {
                        // --- Mobile Behavior ---
                        if (targetVisibleState) {
                            // Close all other panels when opening one
                            document.querySelectorAll('.panel:not(.hidden)').forEach(p => {
                                if (p !== panel) {
                                    p.classList.add('hidden');
                                    console.log(`[直播.html] Mobile: Closed other panel ${p.id}`);
                                }
                            });
                            panel.classList.remove('hidden'); // Show target panel
                        } else {
                            panel.classList.add('hidden'); // Hide target panel
                        }
                        // NO state saving or padding adjustment on mobile toggle
                        console.log(`[直播.html] Mobile toggle finished for ${panelId}. Now hidden: ${!targetVisibleState}`);

                    } else {
                        // --- Desktop Behavior ---
                        if (targetVisibleState) {
                            panel.classList.remove('hidden');
                            panel.style.display = ''; // Ensure display is not none (CSS handles block/flex)
                        } else {
                            panel.classList.add('hidden');
                            panel.style.display = 'none'; // Explicitly set display none for desktop hidden
                        }
                        // Save visibility state to localStorage
                        try {
                            localStorage.setItem(panelStateKey, targetVisibleState); // Save true if visible, false if hidden
